#!/usr/bin/env node
// Validator for the Dependabot Gradle fix-up artifact (the data files the unprivileged
// `dependabot-gradle-fixup` workflow regenerates). The artifact is UNTRUSTED data - the job that
// produced it ran the bumped dependency's build - so a maintainer applies it only after this
// check says it contains nothing beyond what the requested bump explains.
//
//   node gradle-fixup-validate.mjs --head <dir> --artifact <dir> --spec-diff <file> [--strict]
//   node gradle-fixup-validate.mjs --print-allow-list
//
//   --head       the PR head's copies of the allow-listed files plus gradle/libs.versions.toml and
//                settings.gradle.kts (same relative layout as the artifact)
//   --artifact   the downloaded artifact directory (allow-listed files + manifest.json only)
//   --spec-diff  `git diff origin/master...<head> -- gradle/libs.versions.toml settings.gradle.kts
//                build.gradle.kts core/build.gradle.kts server/build.gradle.kts`: what the PR asked for
//
// The report ends in `VERDICT: OK|REVIEW|REFUSED`; exit code 0 / 2 / 1. `--strict` turns REVIEW
// into exit 1. Usage errors exit 64. REFUSED is a hard stop (paths, checksum tampering, grammar,
// a declared version the lockfiles do not honour); REVIEW means the lockfiles moved outside the
// bump (transitive changes, downgrades, configuration-only moves) and a person must read them.
// Metadata additions are listed for the reader; only those outside the bump's groups that no
// lockfile line explains send the verdict to REVIEW.
// Rules and their enforcement: .claude/docs/dependency-reproducibility.md.
import { lstatSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parseArgs } from "node:util";

const METADATA = "gradle/verification-metadata.xml";
const LOCKFILES = [
  "gradle.lockfile",
  "settings-gradle.lockfile",
  "buildscript-gradle.lockfile",
  "core/gradle.lockfile",
  "core/buildscript-gradle.lockfile",
  "server/gradle.lockfile",
  "server/buildscript-gradle.lockfile",
];
const MANIFEST = "manifest.json";
// The ONE allow-list: nothing else may be in the artifact.
const ALLOW_LIST = [METADATA, ...LOCKFILES, MANIFEST];
const MAX_BYTES = 16 * 1024 * 1024;
const KTOR_CATALOG = "io.ktor:ktor-version-catalog";

// H2: constructs that widen what Gradle trusts.
const FORBIDDEN_METADATA_TOKENS = [
  "also-trust",
  "<trust",
  "trusted-artifacts",
  "ignored-keys",
  "trusted-keys",
  "key-servers",
  "<md5",
  "<sha1",
  "<sha512",
];

// H4: the five line shapes Gradle writes (and the only ones an addition may have).
const NAME = '[^"<>&\'\\s]+';
const SHAPE_COMPONENT = new RegExp(`^ *<component group="(${NAME})" name="(${NAME})" version="(${NAME})">$`);
const SHAPE_ARTIFACT = new RegExp(`^ *<artifact name="(${NAME})">$`);
const SHAPE_SHA256 = /^ *<sha256 value="([0-9a-f]{64})" origin="Generated by Gradle"\/>$/;
const SHAPE_ARTIFACT_END = /^ *<\/artifact>$/;
const SHAPE_COMPONENT_END = /^ *<\/component>$/;

// L1: `group:name:version=config,config`, `empty=config,...` or a `#` comment.
const LOCK_ENTRY = /^([^\s:=#]+):([^\s:=#]+):([^\s:=]+)=([A-Za-z0-9_.-]+(?:,[A-Za-z0-9_.-]+)*)$/;
const LOCK_EMPTY = /^empty=[A-Za-z0-9_.,-]*$/;

const EXACT_VERSION = /^[A-Za-z0-9][A-Za-z0-9_.-]*$/;
const VERSION_START = /^\d[\w.+-]*$/;

class Report {
  constructor() {
    this.lines = [];
    this.refusals = 0;
    this.reviews = 0;
  }
  say(text = "") {
    this.lines.push(text);
  }
  refuse(code, text) {
    this.refusals += 1;
    this.lines.push(`REFUSED ${code}: ${text}`);
  }
  review(code, text) {
    this.reviews += 1;
    this.lines.push(`REVIEW ${code}: ${text}`);
  }
  verdict() {
    if (this.refusals > 0) return "REFUSED";
    return this.reviews > 0 ? "REVIEW" : "OK";
  }
}

function usageError(message) {
  process.stderr.write(`${message}\nusage: gradle-fixup-validate.mjs --head <dir> --artifact <dir> --spec-diff <file> [--strict] | --print-allow-list\n`);
  process.exit(64);
}

function readCapped(path) {
  const stat = lstatSync(path);
  if (!stat.isFile()) throw new Error(`${path} is not a regular file`);
  if (stat.size > MAX_BYTES) throw new Error(`${path} is larger than ${MAX_BYTES} bytes`);
  return readFileSync(path, "utf8");
}

function readOptional(dir, rel) {
  try {
    return readCapped(join(dir, rel));
  } catch (error) {
    if (error.code === "ENOENT") return null;
    throw error;
  }
}

// ---------------------------------------------------------------------------------------------
// H1 - the artifact holds the allow-listed regular files and nothing else.
// ---------------------------------------------------------------------------------------------
function checkPaths(artifactDir, report) {
  const present = new Set();
  const walk = (rel) => {
    for (const entry of readdirSync(join(artifactDir, rel), { withFileTypes: true })) {
      const path = rel ? `${rel}/${entry.name}` : entry.name;
      if (path.split("/").some((segment) => segment === ".." || segment === "." || segment === "")) {
        report.refuse("H1", `unsafe path segment in ${JSON.stringify(path)}`);
      } else if (entry.isSymbolicLink()) {
        report.refuse("H1", `symlink ${path}`);
      } else if (entry.isDirectory()) {
        walk(path);
      } else if (!entry.isFile()) {
        report.refuse("H1", `not a regular file: ${path}`);
      } else if (!ALLOW_LIST.includes(path)) {
        report.refuse("H1", `path not on the allow-list: ${path}`);
      } else if (lstatSync(join(artifactDir, path)).size > MAX_BYTES) {
        report.refuse("H1", `${path} is larger than ${MAX_BYTES} bytes`);
      } else {
        present.add(path);
      }
    }
  };
  walk("");
  return present;
}

// ---------------------------------------------------------------------------------------------
// The bump set S: what the PR's spec diff asked for.
// ---------------------------------------------------------------------------------------------
function parseDiffLines(diffText) {
  const files = new Map();
  let current = null;
  for (const line of diffText.split("\n")) {
    if (line.startsWith("diff --git ")) {
      current = null;
    } else if (line.startsWith("+++ ")) {
      const path = line.slice(4).replace(/^b\//, "");
      current = path === "/dev/null" ? null : { path, added: [], removed: [] };
      if (current) files.set(path, current);
    } else if (line.startsWith("--- ")) {
      // header of the old side
    } else if (current && line.startsWith("+")) {
      current.added.push(line.slice(1));
    } else if (current && line.startsWith("-")) {
      current.removed.push(line.slice(1));
    }
  }
  return files;
}

const isComment = (line) => /^\s*(#|\/\/|\*|\/\*)/.test(line);

function quotedStrings(line) {
  return [...line.matchAll(/"([^"]*)"/g)].map((match) => match[1]);
}

// `"g:n:v"` literals of a build/settings script line.
function gavLiterals(line) {
  return [...line.matchAll(/"([^":\s]+):([^":\s]+):([^":\s]+)"/g)].map((match) => ({ module: `${match[1]}:${match[2]}`, version: match[3] }));
}

// One toml entry line: `key = "x"` or `key = { module = "g:n", version.ref = "k" }`.
function parseTomlEntry(line) {
  const match = line.match(/^\s*([A-Za-z0-9_.-]+)\s*=\s*(.+?)\s*$/);
  if (!match) return null;
  const [, key, rawValue] = match;
  const value = rawValue.replace(/\s+#[^"]*$/, "");
  const entry = { key, module: null, versionRef: null, version: null, simple: null };
  if (value.startsWith("{")) {
    const field = (name) => value.match(new RegExp(`(?:[{,]\\s*)${name}\\s*=\\s*"([^"]+)"`))?.[1] ?? null;
    const module = field("module");
    const id = field("id");
    const group = field("group");
    const name = field("name");
    if (module) entry.module = module;
    else if (group && name) entry.module = `${group}:${name}`;
    else if (id) entry.module = `${id}:${id}.gradle.plugin`;
    entry.versionRef = value.match(/version\.ref\s*=\s*"([^"]+)"/)?.[1] ?? value.match(/version\s*=\s*\{[^}]*\bref\s*=\s*"([^"]+)"/)?.[1] ?? null;
    entry.version =
      value.match(/[{,]\s*version\s*=\s*"([^"]+)"/)?.[1] ?? value.match(/version\s*=\s*\{[^}]*\b(?:strictly|require|prefer)\s*=\s*"([^"]+)"/)?.[1] ?? null;
    return entry;
  }
  const quoted = value.match(/^"([^"]*)"$/);
  if (!quoted) return null;
  entry.simple = quoted[1];
  const parts = quoted[1].split(":");
  if (parts.length === 3) {
    entry.module = `${parts[0]}:${parts[1]}`;
    entry.version = parts[2];
  }
  return entry;
}

function parseToml(text) {
  const versions = new Map();
  const libraries = [];
  const unparsed = [];
  let section = "";
  for (const line of text.split("\n")) {
    const header = line.match(/^\s*\[([A-Za-z0-9_.-]+)\]\s*$/);
    if (header) {
      section = header[1];
    } else if (line.trim() !== "" && !isComment(line)) {
      const entry = parseTomlEntry(line);
      if (!entry) unparsed.push(line.trim());
      else if (section === "versions" && entry.simple !== null) versions.set(entry.key, entry.simple);
      else if ((section === "libraries" || section === "plugins") && entry.module) libraries.push(entry);
    }
  }
  return { versions, libraries, unparsed };
}

function computeBumpSet(diffFiles, headToml, headSettings) {
  const bumped = new Set();
  const declared = new Map(); // module -> Set of exact declared versions
  const declare = (module, version) => {
    if (version && EXACT_VERSION.test(version)) {
      if (!declared.has(module)) declared.set(module, new Set());
      declared.get(module).add(version);
    }
  };
  const addedVersions = new Set();
  const warnings = [];

  const changedKeys = new Set();
  for (const file of diffFiles.values()) {
    const before = new Set(file.removed.map((line) => line.trim()));
    const fresh = file.added.filter((line) => !isComment(line) && !before.has(line.trim()));
    for (const line of file.added.filter((added) => !isComment(added))) {
      for (const text of quotedStrings(line)) {
        const parts = text.split(":");
        const candidate = parts.length === 3 ? parts[2] : text;
        if (VERSION_START.test(candidate)) addedVersions.add(candidate);
      }
    }
    if (file.path.endsWith(".toml")) {
      for (const line of fresh) {
        const entry = parseTomlEntry(line);
        if (!entry) warnings.push(`unparsed toml line in the spec diff: ${line.trim()}`);
        else if (entry.module) bumped.add(entry.module);
        else if (entry.simple !== null) changedKeys.add(entry.key);
      }
    } else {
      for (const line of fresh) {
        for (const literal of gavLiterals(line)) {
          bumped.add(literal.module);
          declare(literal.module, literal.version);
        }
      }
    }
  }
  for (const entry of headToml.libraries) {
    const version = entry.version ?? (entry.versionRef ? headToml.versions.get(entry.versionRef) : null);
    if (entry.versionRef && changedKeys.has(entry.versionRef)) bumped.add(entry.module);
    if (bumped.has(entry.module)) declare(entry.module, version);
  }
  // The Ktor catalog coordinate is declared in settings.gradle.kts (also when this PR did not bump it).
  for (const literal of gavLiterals(headSettings ?? "")) if (literal.module === KTOR_CATALOG) declare(literal.module, literal.version);
  return { bumped, declared, addedVersions, warnings, groups: new Set([...bumped].map((module) => module.split(":")[0])) };
}

// Rough version order, only used to spot a DOWNGRADE (never to prove an upgrade is right): numeric
// tokens compare numerically, word tokens lexically, a missing token is smaller than a number and
// larger than a qualifier (1.0 > 1.0-alpha).
function compareVersions(a, b) {
  const left = a.split(/[.\-_+]/);
  const right = b.split(/[.\-_+]/);
  const numeric = (token) => /^\d+$/.test(token);
  for (let index = 0; index < Math.max(left.length, right.length); index += 1) {
    const x = left[index];
    const y = right[index];
    if (x === y) continue;
    if (x === undefined) return numeric(y) ? -1 : 1;
    if (y === undefined) return numeric(x) ? 1 : -1;
    if (numeric(x) && numeric(y)) {
      if (Number(x) !== Number(y)) return Number(x) < Number(y) ? -1 : 1;
    } else if (numeric(x) === numeric(y)) {
      return x < y ? -1 : 1;
    } else {
      return 0; // a number against a word: no opinion
    }
  }
  return 0;
}

const highest = (versions) => versions.reduce((best, version) => (compareVersions(version, best) > 0 ? version : best));

// Tag of one lockfile change: bumped (explained by the requested bump), family (same group as a
// bumped module), other, or one of the shapes that is never "explained": downgrade, configs (only
// the configuration list moved) and removal.
function classifyChange(bumpSet, change) {
  const related = bumpSet.bumped.has(change.module) || bumpSet.groups.has(change.module.split(":")[0]);
  if (change.reconfigured) return "configs";
  if (change.added.length === 0) return related ? "family" : "other";
  if (change.removed.length > 0 && compareVersions(highest(change.added), highest(change.removed)) < 0) return "downgrade";
  return classify(bumpSet, change.module, change.added);
}

function classify(bumpSet, module, versions) {
  if (bumpSet.bumped.has(module)) return "bumped";
  const group = module.split(":")[0];
  if (!bumpSet.groups.has(group)) return "other";
  return versions.length > 0 && versions.every((version) => bumpSet.addedVersions.has(version)) ? "bumped" : "family";
}

// ---------------------------------------------------------------------------------------------
// verification-metadata.xml (H2-H5)
// ---------------------------------------------------------------------------------------------
// Strict line parser: returns { prefix, suffix, components, errors }. A component maps
// artifact name -> sha256.
function parseMetadata(text) {
  const lines = text.split("\n");
  const start = lines.findIndex((line) => /^ *<components>$/.test(line));
  const end = lines.findIndex((line) => /^ *<\/components>$/.test(line));
  const result = { lines, prefix: [], suffix: [], components: new Map(), errors: [] };
  if (start < 0 || end < start) {
    result.errors.push("no <components> ... </components> region");
    return result;
  }
  result.prefix = lines.slice(0, start + 1);
  result.suffix = lines.slice(end);
  let component = null;
  let artifact = null;
  let sha = null;
  for (let index = start + 1; index < end; index += 1) {
    const line = lines[index];
    const at = `line ${index + 1}`;
    let match;
    if (artifact !== null) {
      if ((match = line.match(SHAPE_SHA256))) {
        if (sha !== null) result.errors.push(`${at}: a second sha256 inside artifact ${artifact} of ${component.key}`);
        sha = match[1];
      } else if (SHAPE_ARTIFACT_END.test(line)) {
        if (sha === null) result.errors.push(`${at}: artifact ${artifact} of ${component.key} has no sha256`);
        component.artifacts.set(artifact, sha);
        artifact = null;
        sha = null;
      } else {
        result.errors.push(`${at}: unexpected inside an artifact: ${line.trim()}`);
      }
    } else if (component !== null) {
      if ((match = line.match(SHAPE_ARTIFACT))) {
        if (component.artifacts.has(match[1])) result.errors.push(`${at}: duplicate artifact ${match[1]} in ${component.key}`);
        artifact = match[1];
      } else if (SHAPE_COMPONENT_END.test(line)) {
        result.components.set(component.key, component.artifacts);
        component = null;
      } else {
        result.errors.push(`${at}: unexpected inside a component: ${line.trim()}`);
      }
    } else if ((match = line.match(SHAPE_COMPONENT))) {
      const key = `${match[1]}:${match[2]}:${match[3]}`;
      if (result.components.has(key)) result.errors.push(`${at}: duplicate component ${key}`);
      component = { key, artifacts: new Map() };
    } else {
      result.errors.push(`${at}: unexpected between components: ${line.trim()}`);
    }
  }
  if (component !== null || artifact !== null) result.errors.push("unterminated component or artifact");
  return result;
}

function configurationBlock(text) {
  return text.match(/<configuration>[\s\S]*?<\/configuration>/)?.[0] ?? null;
}

function checkMetadata(headText, newText, report) {
  const headConfig = configurationBlock(headText);
  const newConfig = configurationBlock(newText);
  if (headConfig === null || newConfig === null) report.refuse("H2", "a <configuration> block is missing");
  else if (headConfig !== newConfig) report.refuse("H2", "the <configuration> block differs from the head's");
  const forbidden = FORBIDDEN_METADATA_TOKENS.filter((token) => newText.includes(token));
  if (forbidden.length > 0) report.refuse("H2", `forbidden trust construct(s): ${forbidden.join(", ")}`);

  const headLines = headText.split("\n");
  const newLines = newText.split("\n");
  // H3: the head's lines are a subsequence of the new file (greedy match; also yields the added lines).
  let cursor = 0;
  const matched = new Set();
  let missing = null;
  for (const line of headLines) {
    let found = false;
    while (cursor < newLines.length) {
      if (newLines[cursor] === line) {
        matched.add(cursor);
        cursor += 1;
        found = true;
        break;
      }
      cursor += 1;
    }
    if (!found) {
      missing = line;
      break;
    }
  }
  if (missing !== null) report.refuse("H3", `a line of the head metadata is not in the artifact (changed or removed): ${missing.trim()}`);

  // H4: every added line is one of the five shapes.
  const shapes = [SHAPE_COMPONENT, SHAPE_ARTIFACT, SHAPE_SHA256, SHAPE_ARTIFACT_END, SHAPE_COMPONENT_END];
  const oddities = [];
  newLines.forEach((line, index) => {
    if (!matched.has(index) && !shapes.some((shape) => shape.test(line))) oddities.push(`line ${index + 1}: ${line.trim()}`);
  });
  if (missing === null && oddities.length > 0) {
    report.refuse("H4", `${oddities.length} added line(s) have no allowed shape, first: ${oddities[0]}`);
  }

  // H5: structure, uniqueness, and an unchanged frame around the component region.
  const parsedHead = parseMetadata(headText);
  const parsedNew = parseMetadata(newText);
  if (parsedHead.errors.length > 0) report.refuse("H5", `the head metadata is not in the expected shape: ${parsedHead.errors[0]}`);
  if (parsedNew.errors.length > 0) report.refuse("H5", `${parsedNew.errors.length} structure error(s), first: ${parsedNew.errors[0]}`);
  if (parsedHead.errors.length === 0 && parsedNew.errors.length === 0) {
    if (parsedHead.prefix.join("\n") !== parsedNew.prefix.join("\n") || parsedHead.suffix.join("\n") !== parsedNew.suffix.join("\n")) {
      report.refuse("H5", "the lines around the <components> region differ from the head's");
    }
    for (const [key, artifacts] of parsedHead.components) {
      const next = parsedNew.components.get(key);
      if (!next) report.refuse("H5", `component ${key} was removed`);
      else {
        for (const [name, sha] of artifacts) {
          if (next.get(name) !== sha) report.refuse("H5", `artifact ${name} of ${key} was removed or its checksum changed`);
        }
      }
    }
  }
  return { head: parsedHead, next: parsedNew };
}

// ---------------------------------------------------------------------------------------------
// lockfiles (L1, L2) and their diff against the head
// ---------------------------------------------------------------------------------------------
// -> { modules: Map module -> Map version -> configs string, empty: Set of configurations the file
// records as holding no dependencies }; null when a line breaks the grammar.
function parseLockfile(text, label, report) {
  const modules = new Map();
  const empty = new Set();
  const lines = text.split("\n");
  let bad = 0;
  lines.forEach((line, index) => {
    if (line === "" && index === lines.length - 1) return; // trailing newline
    if (line.startsWith("#")) return;
    if (LOCK_EMPTY.test(line)) {
      for (const configuration of line.slice("empty=".length).split(",")) if (configuration) empty.add(configuration);
      return;
    }
    const match = line.match(LOCK_ENTRY);
    if (!match) {
      bad += 1;
      if (bad === 1) report.refuse("L1", `${label} line ${index + 1} breaks the lockfile grammar: ${line.slice(0, 120)}`);
      return;
    }
    const module = `${match[1]}:${match[2]}`;
    if (!modules.has(module)) modules.set(module, new Map());
    if (modules.get(module).has(match[3])) {
      report.refuse("L1", `${label} line ${index + 1} repeats ${module}:${match[3]}`);
    }
    modules.get(module).set(match[3], match[4]);
  });
  return bad > 0 ? null : { modules, empty };
}

function diffLock(headModules, newModules) {
  const changes = [];
  for (const module of new Set([...headModules.keys(), ...newModules.keys()])) {
    const before = headModules.get(module) ?? new Map();
    const after = newModules.get(module) ?? new Map();
    const removed = [...before.keys()].filter((version) => !after.has(version));
    const added = [...after.keys()].filter((version) => !before.has(version));
    const reconfigured = [...after.keys()].filter((version) => before.has(version) && before.get(version) !== after.get(version));
    if (removed.length + added.length > 0) changes.push({ module, removed, added });
    else if (reconfigured.length > 0) changes.push({ module, removed: [], added: [], reconfigured });
  }
  return changes.sort((a, b) => a.module.localeCompare(b.module));
}

// ---------------------------------------------------------------------------------------------
function run(args) {
  const report = new Report();
  const headDir = args.head;
  const artifactDir = args.artifact;
  const specDiff = readCapped(args["spec-diff"]);

  report.say(`gradle-fixup-validate: ${ALLOW_LIST.length} allow-listed paths`);
  const present = checkPaths(artifactDir, report);
  for (const path of [METADATA, ...LOCKFILES]) {
    if (!present.has(path) && readOptional(headDir, path) !== null) report.refuse("H1", `the artifact lacks ${path}`);
  }
  if (!present.has(METADATA)) report.refuse("H1", `the artifact lacks ${METADATA}`);
  if (report.refusals > 0) {
    report.say("content checks skipped: the artifact's file set is not acceptable");
    return report;
  }
  report.say(`H1 paths: ok (${present.size} files)`);

  const headToml = parseToml(readOptional(headDir, "gradle/libs.versions.toml") ?? "");
  const headSettings = readOptional(headDir, "settings.gradle.kts");
  const bump = computeBumpSet(parseDiffLines(specDiff), headToml, headSettings);
  report.say(`bump set: ${bump.bumped.size} coordinate(s) in ${bump.groups.size} group(s), ${bump.addedVersions.size} added version string(s)`);
  for (const module of [...bump.bumped].sort()) report.say(`  ${module}${bump.declared.has(module) ? `  declared ${[...bump.declared.get(module)].join(", ")}` : ""}`);
  for (const line of headToml.unparsed) report.review("S", `toml line not understood, bump set may be incomplete: ${line.slice(0, 100)}`);
  for (const warning of bump.warnings) report.review("S", warning);

  // metadata
  const headMeta = readOptional(headDir, METADATA);
  const newMeta = readCapped(join(artifactDir, METADATA));
  let metadata = null;
  if (headMeta === null) report.refuse("H2", "the head has no verification metadata to compare against");
  else metadata = checkMetadata(headMeta, newMeta, report);

  // lockfiles
  const newLocks = new Map();
  const headLocks = new Map();
  let lockChanges = 0;
  const lockReport = [];
  const tally = { bumped: 0, family: 0, other: 0, downgrade: 0, configs: 0 };
  for (const path of LOCKFILES) {
    const nextText = readOptional(artifactDir, path);
    const headText = readOptional(headDir, path);
    if (nextText === null) continue;
    const next = parseLockfile(nextText, path, report);
    const before = headText === null ? { modules: new Map(), empty: new Set() } : parseLockfile(headText, `head ${path}`, report);
    if (next === null || before === null) continue;
    newLocks.set(path, next.modules);
    headLocks.set(path, before.modules);
    // L4: a configuration that appears on or vanishes from the `empty=` line changes what is locked
    // (with the default lock mode a configuration absent from the file is silently unlocked).
    const gone = [...before.empty].filter((configuration) => !next.empty.has(configuration));
    const fresh = [...next.empty].filter((configuration) => !before.empty.has(configuration));
    if (gone.length + fresh.length > 0) {
      report.review("L4", `${path}: the set of locked-empty configurations changed (+${fresh.join(",") || "-"} -${gone.join(",") || "-"})`);
    }
    const changes = diffLock(before.modules, next.modules);
    if (changes.length === 0) continue;
    lockReport.push(`  ${path}`);
    for (const change of changes) {
      const tag = classifyChange(bump, change);
      tally[tag] += 1;
      lockChanges += 1;
      const detail = change.reconfigured ? `configurations changed (${change.reconfigured.join(", ")})` : `${change.removed.join(", ") || "-"} -> ${change.added.join(", ") || "-"}`;
      lockReport.push(`    ${tag.padEnd(9)} ${change.module}  ${detail}`);
    }
  }
  // L2: the declared exact version of a bumped coordinate. REFUSED when the artifact contradicts the
  // spec (nothing resolves the declared version, or an entry it moved lands on an undeclared one).
  // REVIEW when a file keeps an undeclared version (a module a project reaches only transitively,
  // or one the spec does not govern there) or loses the declared one: the verdict cannot tell those
  // from a stale artifact, a person can.
  for (const [module, versions] of bump.declared) {
    const declaredText = [...versions].join(", ");
    const paths = [...new Set([...newLocks.keys(), ...headLocks.keys()])];
    const carriers = paths.filter((path) => newLocks.get(path)?.has(module));
    if (carriers.length > 0 && !carriers.some((path) => [...newLocks.get(path).get(module).keys()].some((version) => versions.has(version)))) {
      report.refuse("L2", `no lockfile resolves ${module} to the declared ${declaredText} (found ${carriers.map((path) => `${path}: ${[...newLocks.get(path).get(module).keys()].join("/")}`).join("; ")})`);
    }
    for (const path of paths) {
      const before = headLocks.get(path)?.get(module) ?? new Map();
      const now = newLocks.get(path)?.get(module) ?? new Map();
      const landed = [...now.keys()].filter((version) => !before.has(version) && !versions.has(version));
      const kept = [...now.keys()].filter((version) => before.has(version) && !versions.has(version));
      const lost = [...before.keys()].filter((version) => versions.has(version) && !now.has(version));
      if (landed.length > 0) report.refuse("L2", `${path} moved ${module} to ${landed.join(", ")} but the spec declares ${declaredText}`);
      if (kept.length > 0) report.review("L2", `${path} keeps ${module} on ${kept.join(", ")} while the spec declares ${declaredText}`);
      if (lost.length > 0) report.review("L2", `${path} no longer resolves ${module} to the declared ${lost.join(", ")}`);
    }
  }
  const settingsLock = newLocks.get("settings-gradle.lockfile");
  const settingsVersions = new Set(gavLiterals(headSettings ?? "").filter((literal) => literal.module === KTOR_CATALOG).map((literal) => literal.version));
  if (settingsLock && settingsVersions.size > 0) {
    const locked = settingsLock.get(KTOR_CATALOG);
    const lockedVersions = locked ? [...locked.keys()] : [];
    if (lockedVersions.length !== 1 || !settingsVersions.has(lockedVersions[0])) {
      report.refuse("L2", `settings-gradle.lockfile pins ${KTOR_CATALOG} at ${lockedVersions.join(", ") || "nothing"} but settings.gradle.kts declares ${[...settingsVersions].join(", ")}`);
    }
  }
  report.say(`lockfiles: ${lockChanges} changed coordinate(s) (bumped ${tally.bumped}, family ${tally.family}, other ${tally.other}, downgrade ${tally.downgrade}, configs ${tally.configs})`);
  for (const line of lockReport) report.say(line);
  const unexplained = lockChanges - tally.bumped;
  if (unexplained > 0) {
    report.review("L3", `${unexplained} lockfile change(s) outside the requested bump (family ${tally.family}, other ${tally.other}, downgrade ${tally.downgrade}, configs ${tally.configs}); read them before applying`);
  }

  // metadata additions: listed for the reader; only those that neither the bump nor any lockfile line explains gate (M1)
  if (metadata && metadata.head.errors.length === 0 && metadata.next.errors.length === 0) {
    const locked = new Set();
    for (const modules of newLocks.values()) for (const [module, versions] of modules) for (const version of versions.keys()) locked.add(`${module}:${version}`);
    const added = [];
    for (const [key, artifacts] of metadata.next.components) {
      const old = metadata.head.components.get(key);
      const fresh = old ? [...artifacts.keys()].filter((name) => !old.has(name)) : [...artifacts.keys()];
      if (fresh.length > 0) {
        const [group, name, version] = key.split(":");
        const tag = classify(bump, `${group}:${name}`, [version]);
        added.push({ key, tag, isNew: !old, explained: tag !== "other" || locked.has(key) });
      }
    }
    const counts = { bumped: 0, family: 0, other: 0 };
    for (const entry of added) counts[entry.tag] += 1;
    const unexplainedAdditions = added.filter((entry) => !entry.explained);
    report.say(`metadata additions: ${added.length} component(s) (bumped ${counts.bumped}, family ${counts.family}, other ${counts.other}, unexplained ${unexplainedAdditions.length})`);
    for (const entry of added) report.say(`  ${entry.explained ? entry.tag.padEnd(6) : "UNEXPL"} ${entry.key}${entry.isNew ? "" : " (new artifacts in an existing component)"}`);
    if (unexplainedAdditions.length > 0) {
      report.review("M1", `${unexplainedAdditions.length} checksum component(s) are outside the bump's groups and in no lockfile: ${unexplainedAdditions.slice(0, 5).map((entry) => entry.key).join(", ")}${unexplainedAdditions.length > 5 ? ", ..." : ""}`);
    }
  }
  return report;
}

function main() {
  let values;
  try {
    ({ values } = parseArgs({
      options: {
        head: { type: "string" },
        artifact: { type: "string" },
        "spec-diff": { type: "string" },
        strict: { type: "boolean", default: false },
        "print-allow-list": { type: "boolean", default: false },
      },
      strict: true,
      allowPositionals: false,
    }));
  } catch (error) {
    usageError(error.message);
  }
  if (values["print-allow-list"]) {
    process.stdout.write(`${ALLOW_LIST.join("\n")}\n`);
    return 0;
  }
  for (const option of ["head", "artifact", "spec-diff"]) if (!values[option]) usageError(`missing --${option}`);

  let report;
  try {
    report = run(values);
  } catch (error) {
    report = new Report();
    report.refuse("internal", `the validator could not finish (${error.message}); failing closed`);
  }
  report.say();
  report.say(`VERDICT: ${report.verdict()}`);
  process.stdout.write(`${report.lines.join("\n")}\n`);
  const verdict = report.verdict();
  if (verdict === "OK") return 0;
  if (verdict === "REVIEW") return values.strict ? 1 : 2;
  return 1;
}

process.exitCode = main();
